$canUpdate=Auth::can('transfers','update');$modals=[];
$modal=static function($id,$title,$body)use(&$modals){ob_start();?>
<section id="<?=e($id)?>" class="entity-modal workspace-entity-modal feed-editor livestock-editor conversion-editor butchery-editor butchery-kpi-modal" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="<?=e($id)?>-title"><header><h2 id="<?=e($id)?>-title"><?=e($title)?></h2><button type="button" class="modal-close" data-workspace-modal-close aria-label="Fermer">×</button></header><?=$body?></section>
<?php $modals[]=ob_get_clean();};
$shipmentLabels=['draft'=>'Brouillon','dispatched'=>'Expédiée','partially_received'=>'Réception partielle','received'=>'Reçue','return_pending'=>'Retour à traiter','returned'=>'Retournée'];
$returnLabels=['planned'=>'À expédier','dispatched'=>'En transit','received'=>'Reçu au départ','closed'=>'Clôturé'];
?>
<div class="butchery-workspace transfer-workspace transfer-dossier">
<header class="butchery-heading"><a class="icon-button" href="<?=e(base_url('transfers'))?>" aria-label="Retour aux transferts"><i class="bi bi-arrow-left"></i></a><div><p><?=$t['transfer_type']==='internal'?'Transfert interne':'Transfert inter-site'?></p><h2><?=e($t['transfer_number'])?></h2></div><span class="butchery-status"><?=e($transferLabels[$t['status']]??$t['status'])?></span></header>
<?php if($success):?><div class="app-alert app-alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="app-alert app-alert-error"><?=e($error)?></div><?php endif;?>
<section class="form-panel butchery-slaughter-actions"><div class="butchery-slaughter-toolbar"><h3><?=e($t['source_code'].' → '.$t['destination_code'])?></h3><button type="button" class="btn-secondary" data-workspace-modal-open="transfer-info">Informations</button>
<?php foreach(['draft'=>['submit','Soumettre','create'],'submitted'=>['approve','Valider et réserver','validate'],'approved'=>['reserve','Réserver','validate']] as $state=>$action):if($t['status']===$state&&$source&&Auth::can('transfers',$action[2])):?>
<form method="post" action="<?=e(base_url('transfers/'.$t['id'].'/'.$action[0]))?>" data-confirm="<?=e($action[1].' ce transfert ?')?>"><?=csrf_field()?><button class="btn-primary"><?=e($action[1])?></button></form>
<?php endif;endforeach;?>
<?php if($canUpdate&&$source&&in_array($t['status'],['reserved','partially_shipped'],true)):?><button type="button" class="btn-primary" data-workspace-modal-open="transfer-ship">Expédier</button><?php endif;?>
<?php if($canUpdate&&$source&&in_array($t['status'],['accepted','partially_accepted','returned'],true)&&$sum['shipped_bags']==$sum['received_bags']&&!array_filter($t['returns'],static function($r){return $r['status']!=='received';})):?><form method="post" action="<?=e(base_url('transfers/'.$t['id'].'/close'))?>" data-confirm="Clôturer le transfert et libérer les réservations restantes ?"><?=csrf_field()?><button class="btn-secondary">Clôturer</button></form><?php endif;?>
</div></section>
<div class="butchery-metrics"><?php foreach([['Demandés',$sum['requested_bags'],'requested_bags'],['En transit',max(0,$sum['shipped_bags']-$sum['received_bags']),'transit'],['Acceptés',$sum['accepted_bags'],'accepted_bags'],['Refusés',$sum['rejected_bags'],'rejected_bags']] as $metric):?><button type="button" class="butchery-kpi" data-workspace-modal-open="transfer-quantities-<?=e($metric[2])?>"><strong><?=e(number_format($metric[1],0,',',' '))?></strong><span><?=e($metric[0])?> · sacs</span><i class="bi bi-chevron-right" aria-hidden="true"></i></button><?php ob_start();?><div class="feed-form-body"><div class="table-responsive"><table class="enterprise-table"><thead><tr><th>Produit / format</th><th>Sacs</th></tr></thead><tbody><?php foreach($t['items'] as $item):$quantity=$metric[2]==='transit'?max(0,$item['shipped_bags']-$item['received_bags']):$item[$metric[2]];?><tr><td><?=e($item['product_name'].' · '.$item['format_name'])?></td><td><?=e($quantity)?></td></tr><?php endforeach;?></tbody></table></div></div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Fermer</button></footer><?php $modal('transfer-quantities-'.$metric[2],$metric[0].' · sacs',ob_get_clean());endforeach;?></div>
