<section class="table-panel butchery-history"><header class="butchery-history-heading"><h3>Expéditions</h3><span class="butchery-status"><?=count($t['shipments'])?></span></header><?php if(!$t['shipments']):?><p class="butchery-empty">Aucune expédition enregistrée.</p><?php else:?><div class="table-responsive"><table class="enterprise-table"><thead><tr><th>Référence / départ</th><th>Véhicule</th><th>Expédiés</th><th>À recevoir</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($t['shipments'] as $shipment):?><tr><td><strong><?=e($shipment['shipment_number'])?></strong><small><?=e($date($shipment['dispatched_at']))?></small></td><td><?=e($shipment['vehicle_reference']?:'—')?></td><td><?=array_sum(array_column($shipment['items'],'quantity_bags'))?></td><td><?=array_sum(array_column($shipment['items'],'quantity_bags'))-array_sum(array_column($shipment['items'],'received_bags'))?></td><td><?=e($shipmentLabels[$shipment['status']]??$shipment['status'])?></td><td><?php if($canUpdate&&$destination&&in_array($shipment['status'],['dispatched','partially_received'],true)):?><button type="button" class="btn-primary" data-workspace-modal-open="transfer-receive-<?=e($shipment['id'])?>">Réceptionner</button><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if($t['returns']):?><section class="table-panel butchery-history"><header class="butchery-history-heading"><h3>Retours</h3></header><div class="table-responsive"><table class="enterprise-table"><thead><tr><th>Référence</th><th>Prévu le</th><th>Expédié le</th><th>Reçu le</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($t['returns'] as $r):?><tr><td><?=e($r['return_number'])?></td><?php foreach(['planned_at','dispatched_at','received_at'] as $key):?><td><?=e($date($r[$key]))?></td><?php endforeach;?><td><?=e($returnLabels[$r['status']]??$r['status'])?></td><td><?php if($canUpdate&&(($r['status']==='planned'&&$destination)||($r['status']==='dispatched'&&$source))):?><form method="post" action="<?=e(base_url('transfers/'.$t['id'].'/returns/'.$r['id'].'/'.($r['status']==='planned'?'dispatch':'receive')))?>" data-confirm="Confirmer cette opération de retour ?"><?=csrf_field()?><button class="btn-secondary"><?=$r['status']==='planned'?'Expédier le retour':'Recevoir au départ'?></button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<?php if($t['non_conformities']):?><section class="table-panel butchery-history"><header class="butchery-history-heading"><h3>Écarts de réception</h3></header><div class="table-responsive"><table class="enterprise-table"><thead><tr><th>Référence</th><th>Attendus</th><th>Reçus</th><th>Refusés</th><th>Motif</th><th>Statut</th></tr></thead><tbody><?php foreach($t['non_conformities'] as $nc):?><tr><td><?=e($nc['reference'])?></td><td><?=e($nc['expected_bags'])?></td><td><?=e($nc['received_bags'])?></td><td><?=e($nc['rejected_bags'])?></td><td><?=e($nc['description'])?></td><td><?=e(['open'=>'Ouvert','resolved'=>'Résolu','closed'=>'Clôturé'][$nc['status']]??$nc['status'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<section class="table-panel butchery-history"><header class="butchery-history-heading"><h3>Historique des opérations</h3></header><?php if(!$t['history']):?><p class="butchery-empty">Aucune opération enregistrée.</p><?php else:?><div class="table-responsive"><table class="enterprise-table"><thead><tr><th>Date</th><th>Opération</th><th>Statut obtenu</th><th>Effectuée par</th><th>Note</th></tr></thead><tbody><?php foreach($t['history'] as $h):?><tr><td data-order="<?=e(strtotime($h['created_at']))?>"><?=e($date($h['created_at']))?></td><td><?=e(['create'=>'Création','submit'=>'Soumission','approve_and_reserve'=>'Validation et réservation','approve'=>'Validation','reserve'=>'Réservation','ship'=>'Expédition','receive'=>'Réception','return_dispatch'=>'Expédition du retour','return_receive'=>'Réception du retour','close'=>'Clôture'][$h['action']]??$h['action'])?></td><td><?=e($transferLabels[$h['new_status']]??$h['new_status'])?></td><td><?=e($h['actor_name'])?></td><td><?=e($h['reason']?:'—')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
